import { connection } from "next/server";

import { storage, STORAGE_KEY_PATTERN } from "@/server/storage";

/**
 * Serves files for the local storage driver (development / VPS). With the S3
 * driver, browsers load media straight from the bucket's public URL instead.
 * Keys are random and generated by the server; anything else is rejected.
 */
export async function GET(_request: Request, ctx: RouteContext<"/media/[...key]">) {
  await connection();
  const { key: parts } = await ctx.params;
  const key = parts.join("/");
  if (!STORAGE_KEY_PATTERN.test(key)) return new Response("Not found", { status: 404 });

  const store = storage();
  if (store.name !== "local") return Response.redirect(store.publicUrl(key), 301);

  const object = await store.get(key);
  if (!object) return new Response("Not found", { status: 404 });

  return new Response(new Uint8Array(object.body), {
    headers: {
      "Content-Type": object.contentType,
      "Content-Length": String(object.body.length),
      "Cache-Control": "public, max-age=31536000, immutable",
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; style-src 'unsafe-inline'; sandbox",
    },
  });
}
